package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Refuses an edit of a claim whose editor another user has open, before anything is written. */
public class CheckClaimLock {
    public void check(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository,
            HttpServletRequest request) throws ClaimLockedException {
        if (repository.lockedByOther(claim, Audit.user(request), sheet.today())) {
            throw new ClaimLockedException(String.valueOf(claim.getId()));
        }
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim as the screen sends it, to add or to edit: an amount (up to two decimals; negative only
 * for a correction), a date (yyyy-MM-dd, or blank for the sheet's entry date while it is set, else its today), a note (may be empty)
 * and, for a correction, the number of the settled claim it corrects (blank otherwise).
 */
public record ClaimRequest(String amount, String date, String note, String corrects) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Sheet sheet, @Val Claim claim)
            throws InvalidClaimStatusException {
        claim.checkEditable();
        claim.setAmount(input.amount());
        claim.setDate(input.date() == null ? sheet.today() : input.date());
        claim.setNote(input.note());
        claim.setCorrects(input.corrects());
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Opens the claim's editor for the user: only a draft may be edited, and not while another user
 * has its editor open (on the sheet's today). Any other editor the user had open on the same
 * person's claims is released, as the person's form edits one claim at a time.
 */
public class LockClaim {
    public void lock(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository,
            HttpServletRequest request) throws InvalidClaimStatusException, ClaimLockedException {
        claim.checkEditable();
        String user = Audit.user(request);
        if (!repository.lock(claim, user, sheet.today())) throw new ClaimLockedException(String.valueOf(claim.getId()));
        repository.unlockOthers(claim, user);
    }
}

